"""Print the human's prompts and question answers from Claude Code transcripts.

Usage: python3 -I prompts.py FILE [MAXCHARS]
"""
import json, sys

path = sys.argv[1]
limit = int(sys.argv[2]) if len(sys.argv) > 2 else 4000

for n, line in enumerate(open(path, encoding="utf-8", errors="replace"), 1):
    try:
        event = json.loads(line)
    except ValueError:
        continue
    if not isinstance(event, dict):
        continue
    stamp = str(event.get("timestamp"))[11:19]
    message = event.get("message") if isinstance(event.get("message"), dict) else {}
    result = event.get("toolUseResult") if isinstance(event.get("toolUseResult"), dict) else {}
    if isinstance(result.get("answers"), dict):
        print(f"\n--- L{n} {stamp} ANSWERS ---")
        for q, a in result["answers"].items():
            print(f"Q: {q}\nA: {a}")
        notes = result.get("annotations")
        if notes:
            print("NOTES:", json.dumps(notes)[:limit])
        continue
    if event.get("type") != "user" or event.get("isMeta"):
        continue
    content = message.get("content")
    if isinstance(content, list):
        texts = [b.get("text", "") for b in content if isinstance(b, dict) and b.get("type") == "text"]
        content = "\n".join(texts) if texts else None
    if not isinstance(content, str) or not content.strip():
        continue
    if content.lstrip().startswith("<") and "pasted_content" not in content[:200]:
        # system-injected messages (command output, reminders); show a short marker only
        print(f"\n--- L{n} {stamp} (injected) {' '.join(content.split())[:150]}")
        continue
    print(f"\n--- L{n} {stamp} USER ---\n{content[:limit]}")

