"""Print the assistant's text replies (no tool calls) from a transcript, between two line numbers.

Usage: python3 -I replies.py FILE FROM TO [MAXCHARS]
"""
import json, sys

path, first, last = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
limit = int(sys.argv[4]) if len(sys.argv) > 4 else 6000

for n, line in enumerate(open(path, encoding="utf-8", errors="replace"), 1):
    if n < first or n > last:
        continue
    try:
        event = json.loads(line)
    except ValueError:
        continue
    if not isinstance(event, dict) or event.get("type") != "assistant":
        continue
    message = event.get("message") if isinstance(event.get("message"), dict) else {}
    content = message.get("content")
    if not isinstance(content, list):
        continue
    for block in content:
        if isinstance(block, dict) and block.get("type") == "text" and block.get("text", "").strip():
            print(f"\n--- L{n} {str(event.get('timestamp'))[11:19]} ASSISTANT ---\n{block['text'][:limit]}")

